#!/usr/bin/env python3
"""Batch full-space stability diagnostics for degree-6 origami vertices.

This driver uses ``origami_fullspace_stability.py``.  It expects a nested
configuration list of the form

    CONFIGURATIONS = [
        [
            alpha1,
            rk,
            [
                (phi1, phi2, phi3, phi4),
                (phi1, phi2, phi3, phi4, phi5, phi6),
                ...
            ],
        ],
        ...
    ]

All angles are in radians.  A four-entry fold-angle tuple is interpreted as
the compact D1-symmetric representation and expanded to

    (phi1, phi2, phi3, phi4, phi3, phi2).

A six-entry tuple is interpreted as the full fold-angle vector and is checked
for D1 symmetry.  Two-entry tuples such as (phi2, phi3) are not sufficient:
the full compatible state must first be reconstructed by the code that
produced the symmetry-reduced energy landscape.

For every candidate and finite-difference step, the script reports:

* nonlinear loop-closure residual;
* D1 symmetry residual;
* rank and singular values of the linearized compatibility operator;
* reduced full-space and symmetry-breaking gradient norms;
* eigenvalues of the full, symmetric, and symmetry-breaking Hessian blocks;
* symmetric--symmetry-breaking Hessian coupling;
* stability classification while self-contact constraints are omitted;
* the most unstable compatible fold-angle mode, when one exists.

The script writes:

* ``degree6_stability_summary.csv``: one row per candidate;
* ``degree6_stability_by_step.csv``: one row per candidate and FD step;
* ``degree6_stability_by_configuration.csv``: lower/upper counts by (alpha1, rk);
* ``degree6_stability_details.json``: complete vector/matrix diagnostics.

Interpretation of the relaxed-contact result:

* ``strict_local_minimum`` is a certified survivor in the enlarged compatible
  space in which facet penetration is permitted;
* ``saddle`` or ``not_stationary`` does not by itself prove physical
  instability, because the descending motion may be blocked by self-contact;
* ``singular_configuration`` requires a separate nonlinear treatment;
* ``step_sensitive`` means the numerical classification changed with the
  finite-difference step and should not be used without further analysis.
"""

from __future__ import annotations

import argparse
import csv
import json
import math
import sys
from collections import Counter
from pathlib import Path
from typing import Any, Iterable, Sequence

import numpy as np
from numpy.typing import ArrayLike, NDArray

# Make a copy of origami_fullspace_stability.py in this same directory.
THIS_DIRECTORY = Path(__file__).resolve().parent
if str(THIS_DIRECTORY) not in sys.path:
    sys.path.insert(0, str(THIS_DIRECTORY))

try:
    from origami_fullspace_stability import (
        analyze_symmetry_breaking,
        assemble_symmetric_folds_degree6,
        closure_residual,
        crease_vectors_degree6,
        forward_kinematics,
        symmetry_equalities_degree6,
        tangent_spaces,
        torsional_energy,
    )
except ImportError as exc:  # pragma: no cover - exercised only on setup errors
    raise SystemExit(
        "Could not import origami_fullspace_stability.py. Put that file in "
        f"the same directory as {Path(__file__).name}. Original error: {exc}"
    ) from exc

FloatArray = NDArray[np.float64]


