# silently projected to a different state.
INPUT_CLOSURE_TOLERANCE: float = 1.0e-2
INPUT_SYMMETRY_TOLERANCE: float = 1.0e-2

GRADIENT_TOLERANCE: float = 5.0e-2
EIGENVALUE_TOLERANCE: float = 1.0e-6
RETRACTION_CLOSURE_TOLERANCE: float = 1.0e-9

DEFAULT_OUTPUT_DIRECTORY = Path("degree6_stability_results")


# =============================================================================
# MODEL-SPECIFIC HELPERS
# =============================================================================


def degree6_material_parameters(
    alpha1: float,
    rk: float,
) -> tuple[FloatArray, FloatArray]:
    """Return crease stiffnesses and rest angles used in Section 3(a)."""
    if not np.isfinite(alpha1):
        raise ValueError("alpha1 must be finite.")
    if not np.isfinite(rk) or rk <= 0.0:
        raise ValueError(f"rk must be finite and positive; got {rk!r}.")

    phi_m = -np.pi
    phi_v = np.pi / 2.0

    if alpha1 <= np.pi / 3.0:
        rest_angles = np.array(
            [phi_m, phi_v, phi_v, phi_m, phi_v, phi_v], dtype=float
        )
    else:
        rest_angles = np.array(
            [phi_v, phi_v, phi_m, phi_v, phi_m, phi_v], dtype=float
        )

    k_m = 0.025 * np.sqrt(rk)
    k_v = 0.025 / np.sqrt(rk)
    stiffness = np.where(rest_angles < 0.0, k_m, k_v)
    return stiffness, rest_angles


def expand_fold_angles(fold_angles: Sequence[float]) -> tuple[FloatArray, str]:
    """Convert a compact or full fold-angle tuple to a full six-angle vector."""
    values = np.asarray(fold_angles, dtype=float).reshape(-1)
    if not np.all(np.isfinite(values)):
        raise ValueError("fold-angle tuple contains non-finite entries.")

    if values.size == 4:
        return assemble_symmetric_folds_degree6(*values.tolist()), "compact_D1"
    if values.size == 6:
        return values.copy(), "full_6"
    if values.size == 2:
        raise ValueError(
            "A two-angle tuple (for example, (phi2, phi3)) does not contain "
            "enough information for a full-space stability test. Export the "
            "full compatible six-angle state, or at least "
            "(phi1, phi2, phi3, phi4)."
        )
    raise ValueError(
        "Each fold-angle tuple must contain either 4 entries "
        "(phi1, phi2, phi3, phi4) or all 6 fold angles; "
        f"got {values.size}."
    )


def _norm(vector: ArrayLike) -> float:
    return float(np.linalg.norm(np.asarray(vector, dtype=float)))


def _smallest(values: ArrayLike) -> float:
    array = np.asarray(values, dtype=float).reshape(-1)
    return float(np.min(array)) if array.size else math.nan


def _largest_abs(values: ArrayLike) -> float:
    array = np.asarray(values, dtype=float).reshape(-1)
    return float(np.max(np.abs(array))) if array.size else 0.0


def _matrix_norm(matrix: ArrayLike) -> float:
    return float(np.linalg.norm(np.asarray(matrix, dtype=float), ord="fro"))


def _eigenvalues_symmetric(matrix: ArrayLike) -> FloatArray:
    array = np.asarray(matrix, dtype=float)
    if array.size == 0:
        return np.empty(0, dtype=float)
    return np.linalg.eigvalsh(0.5 * (array + array.T))


def _to_builtin(value: Any) -> Any:
    """Recursively convert NumPy objects to JSON-safe Python objects."""
    if isinstance(value, np.ndarray):
        return _to_builtin(value.tolist())
    if isinstance(value, np.generic):
        return _to_builtin(value.item())
    if isinstance(value, Path):
        return str(value)
    if isinstance(value, dict):
        return {str(key): _to_builtin(item) for key, item in value.items()}
    if isinstance(value, (list, tuple)):
        return [_to_builtin(item) for item in value]
    if isinstance(value, float) and not math.isfinite(value):
        return None
    return value


def _status_interpretation(status: str) -> str:
    interpretations = {
        "strict_local_minimum": (
            "Certified local minimum in the full compatible space when "
            "self-contact constraints are omitted."
        ),
        "saddle": (
            "Stationary but unstable in at least one compatible direction "
            "when self-contact constraints are omitted; contact may still "
            "block the descending mode."
        ),
        "not_stationary": (
            "A first-order compatible descent direction exists when contact "
            "is omitted, or the supplied candidate is not sufficiently "
            "converged as an equilibrium."
        ),
        "marginal_or_inconclusive": (
            "The smallest curvature is within the numerical tolerance; "
            "repeat with additional steps and trace the soft mode."
        ),
        "singular_configuration": (
            "The linearized compatibility operator is rank-deficient; the "
            "ordinary local Hessian test is not valid."
        ),
        "input_not_compatible": (
            "The supplied fold angles do not satisfy nonlinear loop closure "
            "to the requested input tolerance."
        ),
        "input_not_symmetric": (
            "The supplied full fold-angle vector does not satisfy the D1 "
            "relations phi5=phi3 and phi6=phi2 to the requested tolerance."
        ),
        "analysis_error": "The local compatibility retraction or derivative calculation failed.",
        "step_sensitive": (
            "The classification changes with finite-difference step; no "
            "robust conclusion should be drawn yet."
        ),
    }
    return interpretations.get(status, "")


# =============================================================================
# ONE-STATE ANALYSIS
# =============================================================================


def analyze_one_state(
    *,
    group_index: int,
    state_index: int,
    alpha1: float,
    rk: float,
    fold_angles: Sequence[float],
    finite_difference_steps: Sequence[float],
    primary_step: float,
    input_closure_tolerance: float,
    input_symmetry_tolerance: float,
    gradient_tolerance: float,
    eigenvalue_tolerance: float,
    retraction_closure_tolerance: float,
) -> tuple[dict[str, Any], list[dict[str, Any]], dict[str, Any]]:
    """Analyze one candidate and return summary, per-step rows, and details."""
    state_id = f"cfg_{group_index:02d}_state_{state_index:03d}"
    phi, input_format = expand_fold_angles(fold_angles)

    B = crease_vectors_degree6(alpha1)
    stiffness, rest_angles = degree6_material_parameters(alpha1, rk)
    symmetry_matrix = symmetry_equalities_degree6()

    closure_vector = closure_residual(B, phi)
    closure_norm = _norm(closure_vector)
    symmetry_vector = symmetry_matrix @ phi
    symmetry_norm = _norm(symmetry_vector)
    energy = torsional_energy(phi, stiffness, rest_angles)

    base: dict[str, Any] = {
        "state_id": state_id,
        "group_index": group_index,
        "state_index": state_index,
        "alpha1_rad": float(alpha1),
        "alpha1_over_pi": float(alpha1 / np.pi),
        "rk": float(rk),
        "input_format": input_format,
        "phi": phi,
        "stiffness": stiffness,
        "rest_angles": rest_angles,
        "energy_at_supplied_state": energy,
        "closure_vector": closure_vector,
        "closure_norm": closure_norm,
        "symmetry_vector": symmetry_vector,
        "symmetry_norm": symmetry_norm,
        **{f"phi{i + 1}": float(phi[i]) for i in range(6)},
    }

    if closure_norm > input_closure_tolerance:
        print("closure norm = {} > tol, {}".format(closure_norm, input_closure_tolerance))
        summary = {
            **base,
            "consensus_status": "input_not_compatible",
            "primary_status": "input_not_compatible",
            "interpretation": _status_interpretation("input_not_compatible"),
            "successful_step_count": 0,
            "tested_step_count": len(finite_difference_steps),
            "certified_relaxed_survivor": False,
        }
        details = {**base, "runs": [], "error": summary["interpretation"]}
        return summary, [], details

    if symmetry_norm > input_symmetry_tolerance:
        summary = {
            **base,
            "consensus_status": "input_not_symmetric",
            "primary_status": "input_not_symmetric",
            "interpretation": _status_interpretation("input_not_symmetric"),
            "successful_step_count": 0,
            "tested_step_count": len(finite_difference_steps),
            "certified_relaxed_survivor": False,
        }
        details = {**base, "runs": [], "error": summary["interpretation"]}
        return summary, [], details

    # Independent geometric diagnostics at the supplied state.
    spaces = tangent_spaces(
        B,
        phi,
        closure_tolerance=max(input_closure_tolerance, closure_norm * 10.0 + 1.0e-14),
    )
    singular_values = spaces.singular_values
    positive_singular_values = singular_values[singular_values > 1.0e-14]
    jacobian_condition_number = (
        float(positive_singular_values[0] / positive_singular_values[-1])
        if positive_singular_values.size >= 2
        else math.inf
    )
    deformed_creases = forward_kinematics(B, phi).deformed_creases

    base.update(
        {
            "constraint_rank": spaces.rank,
            "tangent_dimension": spaces.tangent_basis.shape[1],
            "compatibility_singular_values": singular_values,
            "compatibility_condition_number": jacobian_condition_number,
            "deformed_creases": deformed_creases,
        }
    )

    per_step_rows: list[dict[str, Any]] = []
    detailed_runs: list[dict[str, Any]] = []

    for step in finite_difference_steps:
        run_base = {
            "state_id": state_id,
            "group_index": group_index,
            "state_index": state_index,
            "alpha1_rad": float(alpha1),
            "alpha1_over_pi": float(alpha1 / np.pi),
            "rk": float(rk),
            "finite_difference_step": float(step),
            "closure_norm": closure_norm,
            "symmetry_norm": symmetry_norm,
            "constraint_rank": spaces.rank,
            "compatibility_condition_number": jacobian_condition_number,
        }

        try:
            result = analyze_symmetry_breaking(
                B,
                phi,
                stiffness,
                rest_angles,
                symmetry_matrix,
                finite_difference_step=float(step),
                gradient_tolerance=gradient_tolerance,
                eigenvalue_tolerance=eigenvalue_tolerance,
                closure_tolerance=retraction_closure_tolerance,
            )
            full = result.full_result
            symmetric_eigenvalues = _eigenvalues_symmetric(result.symmetric_hessian)

            row = {
                **run_base,
                "status": full.status,
                "analysis_succeeded": True,
                "error": "",
                "energy_after_q0_retraction": full.energy,
                "energy_projection_change": full.energy - energy,
                "full_gradient_norm": _norm(full.reduced_gradient),
                "symmetric_gradient_norm": _norm(result.symmetric_gradient),
                "breaking_gradient_norm": _norm(result.breaking_gradient),
                "minimum_full_eigenvalue": _smallest(full.eigenvalues),
                "minimum_symmetric_eigenvalue": _smallest(symmetric_eigenvalues),
                "minimum_breaking_eigenvalue": _smallest(result.breaking_eigenvalues),
                "maximum_abs_full_eigenvalue": _largest_abs(full.eigenvalues),
                "coupling_hessian_norm": _matrix_norm(result.coupling_hessian),
                "symmetric_dimension": result.symmetric_dimension,
                "breaking_dimension": result.breaking_dimension,
            }
            per_step_rows.append(row)

            detailed_runs.append(
                {
                    **row,
                    "full_reduced_gradient": full.reduced_gradient,
                    "full_reduced_hessian": full.reduced_hessian,
                    "full_eigenvalues": full.eigenvalues,
                    "full_eigenvectors_q": full.eigenvectors_q,
                    "symmetric_gradient": result.symmetric_gradient,
                    "breaking_gradient": result.breaking_gradient,
                    "symmetric_hessian": result.symmetric_hessian,
                    "symmetric_eigenvalues": symmetric_eigenvalues,
                    "breaking_hessian": result.breaking_hessian,
                    "breaking_eigenvalues": result.breaking_eigenvalues,
                    "coupling_hessian": result.coupling_hessian,
                    "most_unstable_full_fold_mode": full.most_unstable_fold_mode,
                    "most_unstable_breaking_fold_mode": (
                        result.most_unstable_breaking_fold_mode
                    ),
                }
            )
        except Exception as exc:  # keep the batch alive and expose the failure
            row = {
                **run_base,
                "status": "analysis_error",
                "analysis_succeeded": False,
                "error": f"{type(exc).__name__}: {exc}",
                "energy_after_q0_retraction": math.nan,
                "energy_projection_change": math.nan,
                "full_gradient_norm": math.nan,
                "symmetric_gradient_norm": math.nan,
                "breaking_gradient_norm": math.nan,
                "minimum_full_eigenvalue": math.nan,
                "minimum_symmetric_eigenvalue": math.nan,
                "minimum_breaking_eigenvalue": math.nan,
                "maximum_abs_full_eigenvalue": math.nan,
                "coupling_hessian_norm": math.nan,
                "symmetric_dimension": math.nan,
                "breaking_dimension": math.nan,
            }
            per_step_rows.append(row)
            detailed_runs.append(row)

    successful_rows = [row for row in per_step_rows if row["analysis_succeeded"]]
    successful_statuses = [str(row["status"]) for row in successful_rows]

    if not successful_statuses:
        consensus_status = "analysis_error"
    elif len(set(successful_statuses)) == 1:
        consensus_status = successful_statuses[0]
    else:
        consensus_status = "step_sensitive"

    # Select the primary row exactly when available; otherwise use the nearest
    # successful finite-difference step.
    primary_candidates = [
        row
        for row in successful_rows
        if math.isclose(
            float(row["finite_difference_step"]),
            float(primary_step),
            rel_tol=0.0,
            abs_tol=max(1.0e-16, 1.0e-12 * abs(primary_step)),
        )
    ]
    if primary_candidates:
        primary = primary_candidates[0]
    elif successful_rows:
        primary = min(
            successful_rows,
            key=lambda row: abs(float(row["finite_difference_step"]) - primary_step),
        )
    else:
        primary = {
            "status": "analysis_error",
            "finite_difference_step": math.nan,
            "full_gradient_norm": math.nan,
            "symmetric_gradient_norm": math.nan,
            "breaking_gradient_norm": math.nan,
            "minimum_full_eigenvalue": math.nan,
            "minimum_symmetric_eigenvalue": math.nan,
            "minimum_breaking_eigenvalue": math.nan,
            "coupling_hessian_norm": math.nan,
            "symmetric_dimension": math.nan,
            "breaking_dimension": math.nan,
            "error": "All finite-difference analyses failed.",
        }

    full_minima = [
        float(row["minimum_full_eigenvalue"])
        for row in successful_rows
        if math.isfinite(float(row["minimum_full_eigenvalue"]))
    ]
    breaking_minima = [
        float(row["minimum_breaking_eigenvalue"])
        for row in successful_rows
        if math.isfinite(float(row["minimum_breaking_eigenvalue"]))
    ]

    summary = {
        **base,
        "consensus_status": consensus_status,
        "primary_status": primary["status"],
        "interpretation": _status_interpretation(consensus_status),
        "primary_finite_difference_step": primary["finite_difference_step"],
        "successful_step_count": len(successful_rows),
        "tested_step_count": len(finite_difference_steps),
        "primary_full_gradient_norm": primary["full_gradient_norm"],
        "primary_symmetric_gradient_norm": primary["symmetric_gradient_norm"],
        "primary_breaking_gradient_norm": primary["breaking_gradient_norm"],
        "primary_minimum_full_eigenvalue": primary["minimum_full_eigenvalue"],
        "primary_minimum_symmetric_eigenvalue": primary[
            "minimum_symmetric_eigenvalue"
        ],
        "primary_minimum_breaking_eigenvalue": primary[
            "minimum_breaking_eigenvalue"
        ],
        "primary_coupling_hessian_norm": primary["coupling_hessian_norm"],
        "symmetric_dimension": primary["symmetric_dimension"],
        "breaking_dimension": primary["breaking_dimension"],
        "full_minimum_eigenvalue_range": (
            max(full_minima) - min(full_minima) if len(full_minima) >= 2 else 0.0
        ),
        "breaking_minimum_eigenvalue_range": (
            max(breaking_minima) - min(breaking_minima)
            if len(breaking_minima) >= 2
            else 0.0
        ),
        "expected_dimension_check": (
            spaces.rank == 3
            and spaces.tangent_basis.shape[1] == 3
            and primary["symmetric_dimension"] == 2
            and primary["breaking_dimension"] == 1
        ),
        "status_by_step": "; ".join(
            f"{float(row['finite_difference_step']):.3e}:{row['status']}"
            for row in per_step_rows
        ),
        "certified_relaxed_survivor": (
            consensus_status == "strict_local_minimum"
            and len(successful_rows) == len(finite_difference_steps)
        ),
        "primary_error": primary.get("error", ""),
    }

    details = {**base, "summary": summary, "runs": detailed_runs}
    return summary, per_step_rows, details


# =============================================================================
# BATCH ANALYSIS AND OUTPUT
# =============================================================================


def _validate_configuration_collection(configurations: Sequence[Sequence[Any]]) -> None:
    if not isinstance(configurations, (list, tuple)):
        raise TypeError("configurations must be a list of [alpha1, rk, states] lists.")

    for group_index, configuration in enumerate(configurations, start=1):
        if not isinstance(configuration, (list, tuple)) or len(configuration) != 3:
            raise ValueError(
                f"Configuration {group_index} must be [alpha1, rk, fold_angle_tuples]."
            )
        alpha1, rk, states = configuration
        if not np.isscalar(alpha1) or not np.isscalar(rk):
            raise TypeError(
                f"Configuration {group_index}: alpha1 and rk must be scalars."
            )
        if not isinstance(states, (list, tuple)):
            raise TypeError(
                f"Configuration {group_index}: third element must be a list of "
                "fold-angle tuples."
            )


def run_degree6_batch(
    configurations: Sequence[Sequence[Any]],
    *,
    output_directory: Path | str | None = DEFAULT_OUTPUT_DIRECTORY,
    finite_difference_steps: Sequence[float] = FINITE_DIFFERENCE_STEPS,
    primary_step: float = PRIMARY_FINITE_DIFFERENCE_STEP,
    input_closure_tolerance: float = INPUT_CLOSURE_TOLERANCE,
    input_symmetry_tolerance: float = INPUT_SYMMETRY_TOLERANCE,
    gradient_tolerance: float = GRADIENT_TOLERANCE,
    eigenvalue_tolerance: float = EIGENVALUE_TOLERANCE,
    retraction_closure_tolerance: float = RETRACTION_CLOSURE_TOLERANCE,
    write_files: bool = True,
    print_diagnostics: bool = True,
) -> tuple[list[dict[str, Any]], list[dict[str, Any]], list[dict[str, Any]]]:
    """Run full-space stability diagnostics over the nested configuration list."""
    _validate_configuration_collection(configurations)

    steps = tuple(float(step) for step in finite_difference_steps)
    if not steps or any((not np.isfinite(step) or step <= 0.0) for step in steps):
        raise ValueError("finite_difference_steps must contain positive finite values.")
    if primary_step <= 0.0 or not np.isfinite(primary_step):
        raise ValueError("primary_step must be positive and finite.")

    summaries: list[dict[str, Any]] = []
    per_step_rows: list[dict[str, Any]] = []
    details: list[dict[str, Any]] = []

    for group_index, configuration in enumerate(configurations, start=1):
        alpha1_raw, rk_raw, fold_angle_states = configuration
        alpha1 = float(alpha1_raw)
        rk = float(rk_raw)

        for state_index, fold_angles in enumerate(fold_angle_states, start=1):
            try:
                summary, rows, detail = analyze_one_state(
                    group_index=group_index,
                    state_index=state_index,
                    alpha1=alpha1,
                    rk=rk,
                    fold_angles=fold_angles,
                    finite_difference_steps=steps,
                    primary_step=primary_step,
                    input_closure_tolerance=input_closure_tolerance,
                    input_symmetry_tolerance=input_symmetry_tolerance,
                    gradient_tolerance=gradient_tolerance,
                    eigenvalue_tolerance=eigenvalue_tolerance,
                    retraction_closure_tolerance=retraction_closure_tolerance,
                )
            except Exception as exc:
                state_id = f"cfg_{group_index:02d}_state_{state_index:03d}"
                summary = {
                    "state_id": state_id,
                    "group_index": group_index,
                    "state_index": state_index,
                    "alpha1_rad": alpha1,
                    "alpha1_over_pi": alpha1 / np.pi,
                    "rk": rk,
                    "consensus_status": "analysis_error",
                    "primary_status": "analysis_error",
                    "interpretation": _status_interpretation("analysis_error"),
                    "successful_step_count": 0,
                    "tested_step_count": len(steps),
                    "certified_relaxed_survivor": False,
                    "primary_error": f"{type(exc).__name__}: {exc}",
                }
                rows = []
                detail = {
                    **summary,
                    "raw_fold_angles": list(fold_angles)
                    if isinstance(fold_angles, Iterable)
                    else repr(fold_angles),
                }

            summaries.append(summary)
            per_step_rows.extend(rows)
            details.append(detail)

    group_summaries = build_group_summaries(summaries)

    if print_diagnostics:
        print_summary_table(summaries)
        print_group_summary(group_summaries)
        print_global_summary(summaries)

    if write_files:
        output_path = Path(output_directory or DEFAULT_OUTPUT_DIRECTORY)
        output_path.mkdir(parents=True, exist_ok=True)
        write_csv(output_path / "degree6_stability_summary.csv", summaries)
        write_csv(output_path / "degree6_stability_by_step.csv", per_step_rows)
        write_csv(output_path / "degree6_stability_by_configuration.csv", group_summaries)
        with (output_path / "degree6_stability_details.json").open(
            "w", encoding="utf-8"
        ) as handle:
            json.dump(_to_builtin(details), handle, indent=2, allow_nan=False)

        if print_diagnostics:
            print(f"\nWrote diagnostics to: {output_path.resolve()}")

    return summaries, per_step_rows, details


def _scalar_csv_row(row: dict[str, Any]) -> dict[str, Any]:
    """Drop large arrays from CSV and serialize small arrays compactly."""
    excluded = {
        "phi",
        "stiffness",
        "rest_angles",
        "deformed_creases",
        "full_reduced_hessian",
        "full_eigenvectors_q",
        "symmetric_hessian",
        "breaking_hessian",
        "coupling_hessian",
    }
    converted: dict[str, Any] = {}
    for key, value in row.items():
        if key in excluded:
            continue
        if isinstance(value, np.ndarray):
            converted[key] = json.dumps(value.tolist())
        elif isinstance(value, (list, tuple)):
            converted[key] = json.dumps(_to_builtin(value))
        elif isinstance(value, np.generic):
            converted[key] = value.item()
        else:
            converted[key] = value
    return converted


def write_csv(path: Path, rows: Sequence[dict[str, Any]]) -> None:
    """Write heterogeneous dictionary rows to CSV with stable column ordering."""
    if not rows:
        path.write_text("", encoding="utf-8")
        return

    scalar_rows = [_scalar_csv_row(row) for row in rows]
    preferred = [
        "state_id",
        "group_index",
        "state_index",
        "alpha1_rad",
        "alpha1_over_pi",
        "rk",
        "finite_difference_step",
        "consensus_status",
        "primary_status",
        "status",
        "certified_relaxed_survivor",
        "closure_norm",
        "symmetry_norm",
        "constraint_rank",
        "tangent_dimension",
        "symmetric_dimension",
        "breaking_dimension",
        "compatibility_condition_number",
        "full_gradient_norm",
        "symmetric_gradient_norm",
        "breaking_gradient_norm",
        "minimum_full_eigenvalue",
        "minimum_symmetric_eigenvalue",
        "minimum_breaking_eigenvalue",
        "coupling_hessian_norm",
    ]
    keys = {key for row in scalar_rows for key in row}
    fieldnames = [key for key in preferred if key in keys]
    fieldnames.extend(sorted(keys.difference(fieldnames)))

    with path.open("w", newline="", encoding="utf-8") as handle:
        writer = csv.DictWriter(handle, fieldnames=fieldnames, extrasaction="ignore")
        writer.writeheader()
        writer.writerows(scalar_rows)


def _format_float(value: Any, width: int = 11) -> str:
    try:
        number = float(value)
    except (TypeError, ValueError):
        return "-".rjust(width)
    if not math.isfinite(number):
        return "-".rjust(width)
    return f"{number:.3e}".rjust(width)


def print_summary_table(summaries: Sequence[dict[str, Any]]) -> None:
    """Print one compact diagnostics line per candidate."""
    if not summaries:
        print("No candidate states were supplied in CONFIGURATIONS.")
        return

    header = (
        f"{'state':<20} {'a1/pi':>8} {'rk':>10} {'closure':>11} {'sym':>11} "
        f"{'|g|':>11} {'|gb|':>11} {'lam_min':>11} {'lam_b,min':>11} "
        f"{'consensus':<26}"
    )
    print(header)
    print("-" * len(header))

    for row in summaries:
        print(
            f"{str(row.get('state_id', '-')):<20} "
            f"{float(row.get('alpha1_over_pi', math.nan)):>8.4f} "
            f"{float(row.get('rk', math.nan)):>10.3e} "
            f"{_format_float(row.get('closure_norm'))} "
            f"{_format_float(row.get('symmetry_norm'))} "
            f"{_format_float(row.get('primary_full_gradient_norm'))} "
            f"{_format_float(row.get('primary_breaking_gradient_norm'))} "
            f"{_format_float(row.get('primary_minimum_full_eigenvalue'))} "
            f"{_format_float(row.get('primary_minimum_breaking_eigenvalue'))} "
            f"{str(row.get('consensus_status', '-')):<26}"
        )
        error = str(row.get("primary_error", "") or "")
        if error:
            print(f"    error: {error}")
        if (
            row.get("expected_dimension_check") is False
            and row.get("constraint_rank") == 3
        ):
            print(
                "    warning: expected regular degree-6 dimensions are "
                "tangent=3, symmetric=2, breaking=1; inspect closure precision."
            )


def print_global_summary(summaries: Sequence[dict[str, Any]]) -> None:
    """Print total counts and the relaxed-space lower-bound count."""
    if not summaries:
        return

    counts = Counter(str(row.get("consensus_status", "unknown")) for row in summaries)
    survivors = sum(bool(row.get("certified_relaxed_survivor", False)) for row in summaries)

    print("\nClassification counts")
    print("---------------------")
    for status, count in sorted(counts.items()):
        print(f"{status:<28} {count:>4d}")
    print(f"{'total candidates':<28} {len(summaries):>4d}")
    print(f"{'certified relaxed survivors':<28} {survivors:>4d}")
    print(
        "\nThe certified-survivor count is a lower bound on the number of "
        "physically stable states when unilateral contact is restored."
    )


def build_group_summaries(summaries: Sequence[dict[str, Any]]) -> list[dict[str, Any]]:
    """Aggregate state classifications by the input [alpha1, rk, states] group."""
    grouped: dict[int, list[dict[str, Any]]] = {}
    for row in summaries:
        grouped.setdefault(int(row["group_index"]), []).append(row)

    output: list[dict[str, Any]] = []
    statuses = [
        "strict_local_minimum",
        "saddle",
        "not_stationary",
        "marginal_or_inconclusive",
        "singular_configuration",
        "step_sensitive",
        "input_not_compatible",
        "input_not_symmetric",
        "analysis_error",
    ]
    for group_index, rows in sorted(grouped.items()):
        counts = Counter(str(row.get("consensus_status", "unknown")) for row in rows)
        output.append(
            {
                "group_index": group_index,
                "alpha1_rad": rows[0].get("alpha1_rad", math.nan),
                "alpha1_over_pi": rows[0].get("alpha1_over_pi", math.nan),
                "rk": rows[0].get("rk", math.nan),
                "symmetric_candidate_upper_bound": len(rows),
                "relaxed_survivor_lower_bound": sum(
                    bool(row.get("certified_relaxed_survivor", False)) for row in rows
                ),
                **{f"n_{status}": counts.get(status, 0) for status in statuses},
            }
        )
    return output


def print_group_summary(group_rows: Sequence[dict[str, Any]]) -> None:
    """Print upper/lower state-count bounds for each (alpha1, rk) panel."""
    if not group_rows:
        return
    print("\nPer-configuration bounds")
    print("------------------------")
    print(
        f"{'group':>5} {'a1/pi':>8} {'rk':>10} {'lower':>7} {'upper':>7} "
        f"{'saddle':>7} {'1st-order':>10} {'marginal':>9} {'errors':>7}"
    )
    for row in group_rows:
        errors = (
            int(row.get("n_analysis_error", 0))
            + int(row.get("n_input_not_compatible", 0))
            + int(row.get("n_input_not_symmetric", 0))
            + int(row.get("n_step_sensitive", 0))
        )
        print(
            f"{int(row['group_index']):>5d} "
            f"{float(row['alpha1_over_pi']):>8.4f} "
            f"{float(row['rk']):>10.3e} "
            f"{int(row['relaxed_survivor_lower_bound']):>7d} "
            f"{int(row['symmetric_candidate_upper_bound']):>7d} "
            f"{int(row.get('n_saddle', 0)):>7d} "
            f"{int(row.get('n_not_stationary', 0)):>10d} "
            f"{int(row.get('n_marginal_or_inconclusive', 0)):>9d} "
            f"{errors:>7d}"
        )


# =============================================================================
# COMMAND-LINE ENTRY POINT
# =============================================================================


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--output-dir",
        type=Path,
        default=DEFAULT_OUTPUT_DIRECTORY,
        help="Directory for CSV/JSON diagnostics.",
    )
    parser.add_argument(
        "--no-write",
        action="store_true",
        help="Run and print diagnostics without writing files.",
    )
    return parser.parse_args()


def main() -> int:
    args = parse_args()
    run_degree6_batch(
        CONFIGURATIONS,
        output_directory=args.output_dir,
        write_files=not args.no_write,
        print_diagnostics=True,
    )
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
